function buildFromRecords(records: number[][]): TreeNode | null {
  const left = new Map<number, number>(), right = new Map<number, number>(), parentOf = new Map<number, number>();
  for (const [p, c, isLeft] of records) {
    (isLeft === 1 ? left : right).set(p, c);
    parentOf.set(c, p);
  }
  let rootVal = records[0][0];
  while (parentOf.has(rootVal)) rootVal = parentOf.get(rootVal)!;
  const root = new TreeNode(rootVal);
  const queue: TreeNode[] = [root];
  for (let h = 0; h < queue.length; h++) {
    const node = queue[h];
    if (left.has(node.val)) { node.left = new TreeNode(left.get(node.val)!); queue.push(node.left); }
    if (right.has(node.val)) { node.right = new TreeNode(right.get(node.val)!); queue.push(node.right); }
  }
  return root;
}

