function buildFromRecords(records: number[][]): TreeNode | null {
  const nodes = new Map<number, TreeNode>();
  const children = new Set<number>();
  const get = (v: number) => {
    let node = nodes.get(v);
    if (!node) { node = new TreeNode(v); nodes.set(v, node); }
    return node;
  };
  for (const [p, c, isLeft] of records) {
    const parent = get(p), child = get(c);
    if (isLeft === 1) parent.left = child;
    else parent.right = child;
    children.add(c);
  }
  for (const [p] of records) if (!children.has(p)) return nodes.get(p)!;
  return null;
}

